// Package inventory 判定低库存。这是一个评测 fixture，不是生产代码。
package inventory

import (
	"encoding/json"
	"os"
	"sort"
)

// DefaultLowStockThreshold 是所有**未配置**仓库共用的低库存阈值。
const DefaultLowStockThreshold = 5

// thresholdsPath 是每个仓库阈值配置的来源，相对于服务工作目录。
// 文件不存在、读不了或解析失败时，所有仓库回退到 DefaultLowStockThreshold。
var thresholdsPath = "inventory/thresholds.json"

// LowStockThreshold 返回这个仓库的低库存阈值：先看 inventory/thresholds.json
// 里有没有该仓库的配置，没有就回退到 DefaultLowStockThreshold。
func LowStockThreshold(warehouse string) int {
	if threshold, ok := readThresholds(thresholdsPath)[warehouse]; ok {
		return threshold
	}
	return DefaultLowStockThreshold
}

// readThresholds 从 path 读取 {"<warehouse>": <threshold>} 形式的配置。
// 读不到或解析失败时返回 nil，调用方据此回退到默认值。
func readThresholds(path string) map[string]int {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	var thresholds map[string]int
	if err := json.Unmarshal(data, &thresholds); err != nil {
		return nil
	}
	return thresholds
}
```

