package inventory

import (
	"os"
	"path/filepath"
	"testing"
)

// writeThresholds 在测试临时目录写一份阈值配置，返回它的路径。
func writeThresholds(t *testing.T, body string) string {
	t.Helper()
	path := filepath.Join(t.TempDir(), "thresholds.json")
	if err := os.WriteFile(path, []byte(body), 0o644); err != nil {
		t.Fatalf("写阈值文件失败: %v", err)
	}
	return path
}

// useThresholds 把包级阈值路径临时指向 path，测试结束自动还原。
func useThresholds(t *testing.T, path string) {
	t.Helper()
	old := thresholdsPath
	thresholdsPath = path
	t.Cleanup(func() { thresholdsPath = old })
}

func TestConfiguredWarehouseUsesOwnThreshold(t *testing.T) {
	useThresholds(t, writeThresholds(t, `{"shanghai": 20}`))
	if got := LowStockThreshold("shanghai"); got != 20 {
		t.Fatalf("LowStockThreshold(shanghai) = %d, 期望 20", got)
	}
}

func TestWarehouseMissingFromFileFallsBackToDefault(t *testing.T) {
	useThresholds(t, writeThresholds(t, `{"shanghai": 20}`))
	if got := LowStockThreshold("chengdu"); got != DefaultLowStockThreshold {
		t.Fatalf("未配置仓库应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestMissingThresholdsFileFallsBackToDefault(t *testing.T) {
	useThresholds(t, filepath.Join(t.TempDir(), "does-not-exist.json"))
	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("文件不存在应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

func TestMalformedThresholdsFileFallsBackToDefault(t *testing.T) {
	useThresholds(t, writeThresholds(t, `{"shanghai": `))
	if got := LowStockThreshold("shanghai"); got != DefaultLowStockThreshold {
		t.Fatalf("解析失败应回退默认值 %d，得到 %d", DefaultLowStockThreshold, got)
	}
}

// 配置成 0 是一个合法阈值，不能被当成「没配」而回退。
func TestZeroThresholdIsHonored(t *testing.T) {
	useThresholds(t, writeThresholds(t, `{"shanghai": 0}`))
	if got := LowStockThreshold("shanghai"); got != 0 {
		t.Fatalf("LowStockThreshold(shanghai) = %d, 期望 0", got)
	}
	if IsLowStock("shanghai", 0) {
		t.Fatal("阈值 0 时库存 0 不算低库存（严格小于）")
	}
}

func TestConfiguredThresholdAppliesToStockChecks(t *testing.T) {
	useThresholds(t, writeThresholds(t, `{"shanghai": 20}`))

	if !IsLowStock("shanghai", 19) {
		t.Fatal("19 低于 shanghai 的阈值 20，应算低库存")
	}
	if IsLowStock("shanghai", 20) {
		t.Fatal("20 等于阈值不算低库存（严格小于）")
	}

	got := LowStockWarehouses(map[string]int{"shanghai": 19, "chengdu": 4, "wuhan": 5})
	want := []string{"chengdu", "shanghai"}
	if len(got) != len(want) {
		t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
	}
	for i := range want {
		if got[i] != want[i] {
			t.Fatalf("LowStockWarehouses = %v, 期望 %v", got, want)
		}
	}
}

